package com.ruoyi.medical.persistence;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import org.apache.ibatis.session.Configuration;import org.apache.ibatis.builder.xml.XMLMapperBuilder;import org.apache.ibatis.mapping.SqlCommandType;import net.sf.jsqlparser.parser.CCJSqlParserUtil;import net.sf.jsqlparser.statement.insert.Insert;import java.util.*;
public class FormalCapabilityCancellationMapperTest {
 @Test void actualCancellationSqlIsBoundedAndValid()throws Exception{int n=0;for(String file:List.of("FormalCapabilityCancellationMapper")){var c=new Configuration();try(var in=getClass().getResourceAsStream("/medical-mappers/"+file+".xml")){new XMLMapperBuilder(in,c,file,c.getSqlFragments()).parse();}for(var name:c.getMappedStatementNames())if(name.startsWith("com.ruoyi.medical.persistence.mapper."+file+".")){var ms=c.getMappedStatement(name);var sql=ms.getBoundSql(new HashMap<>()).getSql();var parsed=CCJSqlParserUtil.parse(sql);if(sql.contains("operation_record")){assertTrue(sql.contains("subject_id"));assertFalse(sql.contains("user_id"));}if(ms.getSqlCommandType()==SqlCommandType.SELECT){assertEquals(5,ms.getTimeout());assertTrue(sql.toUpperCase().contains(" LIMIT "),name);assertFalse(ms.isUseCache());}if(parsed instanceof Insert insert){var values=(net.sf.jsqlparser.statement.select.Values)insert.getSelect();assertEquals(insert.getColumns().size(),((net.sf.jsqlparser.expression.operators.relational.ParenthesedExpressionList<?>)values.getExpressions()).size(),name);}if(name.endsWith("markRunning")||name.endsWith("markPassed")){assertTrue(sql.contains("credential_reference_id=?"));assertTrue(sql.contains("config_revision=?"));assertTrue(sql.contains("created_by=?"));assertTrue(sql.contains("revision="));}n++;}}assertEquals(7,n);System.out.println("Checked "+n+" actual capability cancellation mapped statements");}
 public static void main(String[]args)throws Exception{new FormalCapabilityCancellationMapperTest().actualCancellationSqlIsBoundedAndValid();System.out.println("PASS capability cancellation mapper test");}
}
